def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Tile centers are repeated monochrome square patches; the less frequent
    # patch colors are the marked ones. Extend markers only into inter-tile
    # zero gutters, along centerlines to adjacent tiles.
    patches=[]
    for size in range(2, min(h,w)+1):
        for r in range(h-size+1):
            for c in range(w-size+1):
                v=grid[r][c]
                if v and all(grid[r+i][c+j]==v for i in range(size) for j in range(size)):
                    if (r==0 or not all(grid[r-1][c+j]==v for j in range(size))) and (c==0 or not all(grid[r+i][c-1]==v for i in range(size))):
                        patches.append((r,c,size,v))
    # Keep the largest repeated square patches, corresponding to tile interiors.
    if not patches: return out
    maxsize=max(p[2] for p in patches)
    patches=[p for p in patches if p[2]==maxsize]
    counts={v:sum(p[3]==v for p in patches) for _,_,_,v in patches}
    common=max(counts.values())
    rare={v for v,n in counts.items() if n<common}
    centers={(r,c):(s,v) for r,c,s,v in patches}
    for (r,c),(s,v) in centers.items():
        if v not in rare: continue
        # Neighbor patch horizontally: project across the blank gap only.
        for (rr,cc),(ss,vv) in centers.items():
            if rr==r and abs(cc-c)>0:
                if cc>c:
                    for x in range(c+s,cc):
                        if all(grid[y][x]==0 for y in range(r,r+s)):
                            for y in range(r,r+s): out[y][x]=v
                    break
                else:
                    for x in range(cc+ss,c):
                        if all(grid[y][x]==0 for y in range(r,r+s)):
                            for y in range(r,r+s): out[y][x]=v
                    break
        # Neighbor patch vertically.
        for (rr,cc),(ss,vv) in centers.items():
            if cc==c and rr!=r:
                if rr>r:
                    for y in range(r+s,rr):
                        if all(grid[y][x]==0 for x in range(c,c+s)):
                            for x in range(c,c+s): out[y][x]=v
                    break
                else:
                    for y in range(rr+ss,r):
                        if all(grid[y][x]==0 for x in range(c,c+s)):
                            for x in range(c,c+s): out[y][x]=v
                    break
    return out
