def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    # Repeating tiles have 3x3 interiors on a 7-cell lattice. Less frequent
    # interior colors are marked; link matching tiles along aligned core rows/cols.
    pitch=7; start=2
    tiles=[]
    for r in range(start,h, pitch):
        row=[]
        for c in range(start,w,pitch):
            if r+2<h and c+2<w:
                row.append((grid[r][c],r,c))
        tiles.append(row)
    from collections import Counter
    counts=Counter(v for row in tiles for v,_,_ in row if v not in (0,4))
    if not counts:return out
    common=max(counts.values())
    rare={v for v,n in counts.items() if n<common}
    nr=len(tiles); nc=max((len(row) for row in tiles),default=0)
    # Each pair of equal rare tiles on a common tile row connects across the gap,
    # but leaves other colored interiors intact.
    for tr,row in enumerate(tiles):
        for a in range(len(row)):
            va,ra,ca=row[a]
            if va not in rare: continue
            for b in range(a+1,len(row)):
                vb,rb,cb=row[b]
                if vb!=va: continue
                for dr in range(3):
                    rr=ra+dr
                    for cc in range(ca+3,cb):
                        if grid[rr][cc] in (0,4): out[rr][cc]=va
    # same for columns
    for tc in range(nc):
        col=[]
        for tr in range(nr):
            if tc<len(tiles[tr]):col.append(tiles[tr][tc])
        for a in range(len(col)):
            va,ra,ca=col[a]
            if va not in rare:continue
            for b in range(a+1,len(col)):
                vb,rb,cb=col[b]
                if vb!=va:continue
                for dc in range(3):
                    cc=ca+dc
                    for rr in range(ra+3,rb):
                        if grid[rr][cc] in (0,4):out[rr][cc]=va
    return out
