def transform(grid):
    # Every instance is solved from the 7-spaced repeated tile layout. Only
    # uniform 3x3 tile interiors that are less frequent than the dominant
    # interior color are exceptional markers; extend those through zero gaps.
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    centers=[]
    for r in range(2,h,7):
        for c in range(2,w,7):
            if r+2<h and c+2<w:
                v=grid[r][c]
                if v!=0 and all(grid[r+i][c+j]==v for i in range(3) for j in range(3)):
                    centers.append((r+1,c+1,v))
    from collections import Counter
    counts=Counter(v for _,_,v in centers)
    if not counts:return out
    dominant=max(counts.values())
    markers={v for v,n in counts.items() if n<dominant}
    for r,c,v in centers:
        if v not in markers: continue
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            rr,cc=r+dr,c+dc
            while 0<=rr<h and 0<=cc<w and grid[rr][cc]==0:
                out[rr][cc]=v
                rr+=dr;cc+=dc
    return out
